// Safari can expose a layout viewport taller than the area above its toolbars.
export function viewportBox(win){const width=win.document?.documentElement?.clientWidth||win.innerWidth;const raw=win.visualViewport;const stale=raw&&(!raw.scale||raw.scale===1)&&Math.abs(raw.width-width)>2;const v=stale?null:raw;return{width:Math.max(1,Math.floor(v?.width||width)),height:Math.max(1,Math.floor(v?.height||win.innerHeight)),top:Math.max(0,Math.round(v?.offsetTop||0)),left:Math.max(0,Math.round(v?.offsetLeft||0))};}
export function installViewport({win=window,shell=document.getElementById('game-shell'),resize=()=>{}}={}){let frame=0,last='';const apply=()=>{frame=0;const v=viewportBox(win),key=Object.values(v).join(',');if(key===last)return;last=key;shell.style.setProperty('--view-width',v.width+'px');shell.style.setProperty('--view-height',v.height+'px');shell.style.setProperty('--view-top',v.top+'px');shell.style.setProperty('--view-left',v.left+'px');resize(v);};const schedule=()=>{apply();if(!frame)frame=win.requestAnimationFrame(apply);};for(const event of ['resize','orientationchange','pageshow'])win.addEventListener(event,schedule);for(const event of ['resize','scroll'])win.visualViewport?.addEventListener(event,schedule);apply();return{refresh:schedule,destroy(){for(const event of ['resize','orientationchange','pageshow'])win.removeEventListener(event,schedule);for(const event of ['resize','scroll'])win.visualViewport?.removeEventListener(event,schedule);if(frame)win.cancelAnimationFrame(frame);}};}
